CREATE TABLE invitations (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,inviter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,invitee_id TEXT NOT NULL DEFAULT '',token_hash TEXT NOT NULL UNIQUE,role TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,expires_at TEXT NOT NULL,responded_at TEXT NOT NULL DEFAULT '');
CREATE TABLE comments (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE,author_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body_ciphertext BLOB NOT NULL,key_generation INTEGER NOT NULL,change_seq INTEGER NOT NULL,created_at TEXT NOT NULL,deleted_at TEXT NOT NULL DEFAULT '');
CREATE TABLE mentions (comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE,mentioned_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(comment_id,mentioned_user_id));
CREATE TABLE activity (id TEXT PRIMARY KEY,container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE,actor_user_id TEXT NOT NULL,event TEXT NOT NULL,object_id TEXT NOT NULL DEFAULT '',detail_ciphertext BLOB NOT NULL DEFAULT x'',change_seq INTEGER NOT NULL,created_at TEXT NOT NULL);
